/**
 * The Flows list shows each row's wire `http_version` next to its Protocol
 * badge: HTTP/2 streams are recorded as `protocol: "http"`, so the version
 * is the only thing that tells an h2 / h2c row from HTTP/1.x. The fixture
 * is a real `query resource=flows` response generated by
 * internal/mcp/webui_http_fixture_test.go.
 */

import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import type { FlowEntry, FlowsResult } from "../../lib/mcp/types.js";
import flowsText from "../../pages/Flows/__fixtures__/flows-all-protocols.response.json?raw";
import flowsPageSrc from "../../pages/Flows/FlowsPage.tsx?raw";
import { HttpVersionBadge } from "./HttpVersionBadge.js";

const flows = JSON.parse(flowsText) as FlowsResult;

function row(id: string): FlowEntry {
  const f = flows.flows.find((e) => e.id === id);
  if (!f) throw new Error(`fixture has no row ${id}`);
  return f;
}

function render(flow: Pick<FlowEntry, "protocol" | "http_version">): string {
  return renderToStaticMarkup(createElement(HttpVersionBadge, { flow }));
}

function badgeText(html: string): string {
  return /<span class="badge[^"]*">([^<]*)<\/span>/.exec(html)?.[1] ?? "";
}

describe("HttpVersionBadge on flows list rows", () => {
  it("shows h2 / h2c highlighted for recorded HTTP/2 rows", () => {
    for (const [id, want] of [
      ["stream-http-h2", "h2"],
      ["stream-http-h2c", "h2c"],
    ] as const) {
      const html = render(row(id));
      expect(badgeText(html)).toBe(want);
      expect(html).toContain("badge--info");
    }
  });

  it("shows http/1.1 verbatim, not highlighted, for HTTP/1.1, WS and SSE rows", () => {
    for (const id of ["stream-http-h1", "stream-ws", "stream-sse"]) {
      const html = render(row(id));
      expect(badgeText(html)).toBe("http/1.1");
      expect(html).toContain("badge--default");
      expect(html).not.toContain("badge--info");
    }
  });

  it("renders nothing for rows without a version", () => {
    for (const id of ["stream-grpc", "stream-grpc-web", "stream-raw", "stream-tls-handshake"]) {
      expect(render(row(id))).toBe("");
    }
    expect(render({ protocol: "http" })).toBe("");
    expect(render({ protocol: "http", http_version: "" })).toBe("");
  });
});

describe("FlowsPage", () => {
  it("renders each row's HttpVersionBadge in the Protocol cell", () => {
    expect(flowsPageSrc).toMatch(/<HttpVersionBadge flow=\{flow\} \/>/);
  });
});
